+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+ */
+
+#include "windowbuttonlayout.h"
+
+#include <KConfigGroup>
+#include <KSharedConfig>
+
+using namespace Qt::StringLiterals;
+
+WindowButtonLayout::WindowButtonLayout(QObject *parent)
+    : QObject(parent)
+    , m_configWatcher(KConfigWatcher::create(KSharedConfig::openConfig(u"kwinrc"_s)))
+{
+    connect(m_configWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group) {
+        if (group.name() == "org.kde.kdecoration2"_L1) {
+            load();
+        }
+    });
+    load();
+}
+
+bool WindowButtonLayout::buttonsOnLeft() const
+{
+    return m_buttonsOnLeft;
+}
+
+void WindowButtonLayout::load()
+{
+    // Same defaults as KWin: the close button ("X") is on the right
+    const KConfigGroup group = m_configWatcher->config()->group(u"org.kde.kdecoration2"_s);
+    const bool buttonsOnLeft = group.readEntry("ButtonsOnLeft", u"MS"_s).contains(u'X');
+    if (m_buttonsOnLeft != buttonsOnLeft) {
+        m_buttonsOnLeft = buttonsOnLeft;
+        Q_EMIT buttonsOnLeftChanged();
+    }
+}
